import{_ as s,l as n,o as e,c as o,v as r,p as l,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"完美散列","description":"","frontmatter":{"title":"完美散列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/perfect-hashing.md","filePath":"cs/perfect-hashing.md","lastUpdated":1789023840000}'),c={name:"cs/perfect-hashing.md"};function m(_,a,E,f,u,S){const i=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="完美散列" tabindex="-1">完美散列 <a class="header-anchor" href="#完美散列" aria-label="Permalink to &quot;完美散列&quot;">​</a></h1><div class="epigraph"><p>键集已知且不再变：可以造一张没有碰撞的表，查找最坏常数次探测。</p><footer>—— 据 Fredman, Komlós and Szemerédi, Storing a Sparse Table with O(1) Worst Case Access Time, JACM 1984；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/universal-hashing">上一课</a> 保证期望，单次仍可能撞。<a href="/cs/robin-cuckoo">布谷</a> 最坏查找常数但插入可能重建。静态只读字典（保留字、协议码点）可以预处理到零碰撞。本课不换种子对抗。缺口是完美散列：FKS 两级，或 CHD 等实践方案点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态集 \\(S\\)，\\(|S|=n\\)，成员查询。完美：\\(h\\) 在 \\(S\\) 上单射。最小完美：值域也是 \\(n\\) 槽。FKS：一级 \\(h\\) 把键分桶，桶 \\(i\\) 大小 \\(n_i\\)，二级表长 \\(\\Theta(n_i^2)\\) 使桶内完美（期望二级空间合计 \\(O(n)\\)）。缺口是<strong>用空间换掉运行时碰撞</strong>，查找两次散列最坏 \\(O(1)\\)。</p><p><span class="marginnote">Fredman–Komlós–Szemerédi, <em>JACM</em>, 1984。实践 gperf、CHD、BBHash 等，本课不把压缩完美散列论文逐篇列成百科。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造：反复抽通用 \\(h\\) 直到一级桶的 \\(\\sum n_i^2=O(n)\\)，每桶再抽二级 \\(h_i\\)。失败重抽，期望尝试常数。查询：一级下标，二级下标，比较键（避免假命中）。</p>',8)),(e(),l(p,null,{default:t(()=>[h(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E9%9D%99%E6%80%81%E9%94%AE%E9%9B%86%20S%22%5D%20--%3E%20H1%5B%22%E4%B8%80%E7%BA%A7%E5%88%86%E6%A1%B6%22%5D%0A%20%20H1%20--%3E%20H2%5B%22%E6%AF%8F%E6%A1%B6%E5%B9%B3%E6%96%B9%E7%A9%BA%E9%97%B4%E5%AE%8C%E7%BE%8E%22%5D%0A%20%20H2%20--%3E%20Q%5B%22%E6%9C%80%E5%9D%8F%20O(1)%20%E6%9F%A5%E6%89%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与开放寻址：完美无墓碑、无聚集，但不能插入新键除非重建。与布隆：完美无假阳性，但必须存键或确认比较。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空间 \\(O(n)\\) 词级；最小完美更省槽但构造更烦。更新：任意插入可能破坏单射，合同是静态。通用族保证能抽到好 \\(h\\)。</p><p>槽位增减、缓存分布式：下一课一致性哈希，问题从「碰撞」换成「谁负责这个键」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不要求交 FKS 实现作业。动态完美散列存在但复杂，主干不提前。过滤器允许误差，后面草图课再放宽。</p><p>后课默认：静态只读无碰撞用完美散列。节点增减时的键映射用一致性哈希。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完美散列：静态集最坏 \\(O(1)\\)，FKS 两级期望线性空间。</li><li>不能廉价插入。</li><li>分布式槽重映射是一致性哈希。</li><li>出处：Fredman, Komlós and Szemerédi, <em>JACM</em>, 1984；Cormen et al.。</li></ul>',9))])}const T=s(c,[["render",m]]);export{B as __pageData,T as default};
